import{_ as o,o as a,c as i,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0064 — Terminale integrato e finestra separata del terminale (M23)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0064-terminale-integrato-e-finestra-separata.md","filePath":"adr/0064-terminale-integrato-e-finestra-separata.md"}'),t={name:"adr/0064-terminale-integrato-e-finestra-separata.md"};function l(r,e,s,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0064-—-terminale-integrato-e-finestra-separata-del-terminale-m23" tabindex="-1">ADR-0064 — Terminale integrato e finestra separata del terminale (M23) <a class="header-anchor" href="#adr-0064-—-terminale-integrato-e-finestra-separata-del-terminale-m23" aria-label="Permalink to &quot;ADR-0064 — Terminale integrato e finestra separata del terminale (M23)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-20, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.8 (2026-11-20), che lo dichiara «M23 (1.8.0)» (il tag 1.8.0 seguirà); <strong>implementato in M23 (Onde A, B e C) e non provato su una finestra reale</strong>: ConPTY e Job Object sono provati solo in compilazione (<code>task vet-windows</code>), il runbook <a href="./../qa/m23-terminale.html"><code>m23-terminale.md</code></a> è a carico dell&#39;owner; le licenze della decisione 17 sono state controllate il 2026-11-20: tutte MIT. Emenda <a href="./0051-wails-v3.html">ADR-0051</a> (il punto «niente pop-out», limitatamente al terminale), <strong>accettato il 2026-11-20</strong> (opzione A della proposta di spec v1.8)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.8 (2026-11-20): V-02, A-03, §2.2.1 (tre righe: «Pannelli, tab, split…», «Finestre separate (pop-out)» e la riga nuova «Terminale integrato», P2), §2.5 (<code>platform</code> e riga <code>terminal</code>), §2.8.3, §3.7, §4.2, App. B, C.2 (con la riga di rischio facoltativa) e C.4; <a href="./../spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a> §5 resta come storia</td></tr><tr><td><strong>Data</strong></td><td>2026-11-20</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>V-02 (<code>Specifications.md:56</code>); A-03 (<code>:70</code>); §2.2.1, righe «Pannelli, tab, split…» (<code>:356</code>) e «Finestre separate (pop-out)» (<code>:357</code>); §2.5, riga <code>platform</code> (<code>:495</code>); §2.8.3, eccezioni di parità (<code>:691</code>); §3.7 (<code>:1532</code>); §4.2 (<code>:1760</code>, <code>:1769</code>); App. B, riga «Post-1.0 (P2)» (<code>:1939</code>); D-07 (<code>:1955</code>); C.2 (<code>:1979</code>); <a href="./0029-web-workbench.html">ADR-0029</a>, <a href="./0030-desktop-core-wasm.html">ADR-0030</a>, <a href="./0037-registro-funzioni-e-cloud-features.html">ADR-0037</a>, <a href="./0045-parita-per-costruzione.html">ADR-0045</a>, <a href="./0047-apertura-file-per-tipo-e-presentazioni-marp.html">ADR-0047</a>, <a href="./0049-editor-live-milkdown.html">ADR-0049</a>, <a href="./0051-wails-v3.html">ADR-0051</a></td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>sì</strong> → <strong>recepito nello spec v1.8</strong> (2026-11-20; <a href="./../spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a> §5): A-03 e la riga «Finestre separate (pop-out)» ammettono due finestre solo per il terminale; nuove righe per il terminale in §2.2.1, §2.5, §2.8.3 e §4.2 (elenco in «Sezioni dello spec da aggiornare»)</td></tr><tr><td><strong>Superfici</strong></td><td><strong>desktop</strong> (macOS, Windows, Linux; prove: <code>go test -race</code> su <code>internal/terminal</code> e <code>internal/app</code>, <code>task vet-windows</code>, <code>task vet-linux</code>, vitest, <code>task e2e</code> sul mock dei binding, runbook manuale) · <strong>workbench web: eccezione di parità</strong> (il browser non può avviare processi; capability <code>terminal</code> falsa, voce di registro con workbench «no», prova <code>skipOnWeb</code>) · console e cloud: nessuna modifica · Config Profile: <strong>nessun flag</strong></td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>L&#39;owner ha chiesto (2026-11-20, schizzo annotato) un <strong>terminale dentro Clarae</strong>: un pulsante nella ribbon, subito sopra le Impostazioni, apre un pannello con più tab, ognuno con la propria shell, con la cartella di lavoro nella radice del vault aperto. Il pannello è ridimensionabile e si ancora in basso (default), a sinistra o a destra, con la preferenza che resta. Un pulsante all&#39;estrema destra della barra dei tab lo <strong>stacca in una finestra separata del sistema</strong> e lo riattacca, <strong>senza riavviare le shell</strong>. Chiudere un tab, la finestra separata o l&#39;app termina i processi, senza orfani.</p><p>Stato del codice (verificato il 2026-11-20):</p><ul><li>Non esiste un terminale. <code>github.com/creack/pty</code> è solo una dipendenza transitiva (v1.1.24, in <code>apps/desktop/go.sum:29-30</code>; nessun pacchetto del repository la importa); non c&#39;è <code>@xterm/*</code>.</li><li>La finestra è una sola: <code>apps/desktop/main.go:146</code> (<code>wa.Window.NewWithOptions</code>). Gli eventi Go→TS vanno a tutte le finestre (<code>apps/desktop/internal/shell/host.go:121</code>, <code>Host.Emit</code>).</li><li>Il layout del workbench (<code>packages/workbench/src/workspace/layout.ts</code>) descrive solo l&#39;area dell&#39;editor: non c&#39;è un pannello inferiore.</li><li>La CSP del desktop di rilascio ha <code>connect-src &#39;self&#39;</code> (<code>apps/desktop/internal/app/csp_prod.go:14</code>): niente WebSocket verso un servizio locale. L&#39;I/O di un terminale deve passare dai binding ed eventi Wails, come tutto il resto del frontend.</li><li>L&#39;uscita dell&#39;app ha un watchdog di 3 secondi (<code>QuitWatchdog</code>, <code>apps/desktop/internal/shell/lifecycle.go:15</code>) e chiude i servizi da <code>App.Shutdown</code> (<code>apps/desktop/internal/app/app.go:237</code>), dove oggi si chiudono anche le viste native (<code>shutdownWebViews</code>, <code>:241</code>).</li><li>Il sapere se un vault è in sola lettura è già nel core: <code>sync.Manager.ReadOnly(ctx, localID)</code> è vero per un lettore (viewer) di un mount e per un mount la cui condivisione è stata revocata (<code>apps/desktop/internal/sync/mounts.go:229-232</code>).</li></ul><p><strong>Decisioni dell&#39;owner (2026-11-20):</strong></p><ol><li><strong>Nessun flag</strong> del Config Profile: il terminale è sempre disponibile sul desktop.</li><li><strong><code>cwd</code> = radice del vault aperto</strong> (la home se non c&#39;è un vault).</li><li><strong>Sola lettura: il terminale non si apre nei vault in sola lettura.</strong> Il pulsante è disabilitato; il core rifiuta l&#39;apertura con l&#39;errore <code>terminal-read-only</code>; le sessioni aperte in un vault che diventa di sola lettura (revoca della condivisione, ruolo di lettore) vengono chiuse con motivo <code>read-only</code>. <em>Questa decisione sostituisce quella presa lo stesso giorno in un primo momento («<code>cwd</code> = radice del vault anche per i mount in sola lettura»), che avrebbe lasciato aggirare la sola lettura.</em></li><li><strong>Il workbench web non ha il terminale</strong>: è un&#39;eccezione di parità dichiarata.</li><li>La finestra separata è una vera finestra del sistema (di qui le deviazioni da A-03, dalla riga «Finestre separate (pop-out)» e da ADR-0051).</li></ol><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="funzione" tabindex="-1">Funzione <a class="header-anchor" href="#funzione" aria-label="Permalink to &quot;Funzione&quot;">​</a></h3><ol><li><strong>Terminale multi-tab nel client desktop.</strong> Ogni tab è una <strong>shell dell&#39;utente</strong> in uno pseudo-terminale: <code>github.com/creack/pty</code> su macOS e Linux (MIT, Go puro), <strong>ConPTY</strong> su Windows (<code>CreatePseudoConsole</code> tramite <code>golang.org/x/sys/windows</code>, già dipendenza di <code>apps/desktop/go.mod:24</code>; build senza CGO, come per <code>task vet-windows</code>). Nel frontend si usa <strong>xterm.js</strong> (<code>@xterm/xterm</code>, <code>@xterm/addon-fit</code>, <code>@xterm/addon-web-links</code>, MIT), caricato in modo <strong>lazy</strong> (<code>lazyView</code>, stili con <code>linkLazyStyles</code>), così il budget iniziale resta invariato.</li><li><strong>Shell.</strong> Unix: <code>$SHELL -l</code>, con ripiego <code>/bin/zsh</code>, <code>/bin/bash</code>, <code>/bin/sh</code>. Windows: <code>pwsh.exe</code>, poi <code>powershell.exe</code>, poi <code>%ComSpec%</code>. L&#39;ambiente è quello dell&#39;app più <code>TERM=xterm-256color</code>, <code>COLORTERM=truecolor</code> e <code>TERM_PROGRAM=Clarae</code>.</li><li><strong><code>cwd</code>.</strong> Il binding riceve un <code>vaultId</code> (non un percorso): il core risolve la radice tra i vault aperti (<code>App.vaults</code>, <code>apps/desktop/internal/app/app.go:70</code>) e <strong>non accetta percorsi dal frontend</strong>. Nessun vault, o un id sconosciuto: la home dell&#39;utente.</li><li><strong>Sola lettura (decisione 3).</strong> <code>Open</code> su un vault per cui <code>sync.Manager.ReadOnly</code> è vero fallisce con <code>terminal-read-only</code>, senza avviare nulla. Il pulsante della ribbon e i comandi sono disabilitati con quel vault corrente (con un tooltip che ne dice il motivo). Quando un vault aperto passa a sola lettura (<code>UpdateMount</code>, revoca), il core chiude le sue sessioni, e l&#39;evento di uscita porta il motivo <code>read-only</code>; il tab mostra un messaggio, non un errore generico. <strong>Limite dichiarato:</strong> la regola vale per il vault della sessione, non per il computer. Una shell aperta in un vault <strong>scrivibile</strong> è una shell dell&#39;utente e può leggere e scrivere ovunque l&#39;utente possa, anche <strong>fuori dalle regole dell&#39;app</strong>: altri vault, il contenuto di un mount in sola lettura aperto come cartella, <code>.clarae/</code> e <code>sync.db</code>, qualunque altro file. Il terminale non è un confine di sicurezza e non fa rispettare i permessi di condivisione: questi restano imposti dal cloud e dall&#39;app. Un file di un mount in sola lettura modificato così da fuori dall&#39;app resta, come oggi, una modifica locale non inviata.</li></ol><h3 id="pannello-e-finestra-separata" tabindex="-1">Pannello e finestra separata <a class="header-anchor" href="#pannello-e-finestra-separata" aria-label="Permalink to &quot;Pannello e finestra separata&quot;">​</a></h3><ol start="5"><li><strong>Pannello ancorabile</strong> in basso, a sinistra o a destra dell&#39;area di lavoro, ridimensionabile. Posizione e dimensione sono <strong>preferenze per dispositivo</strong> in <code>localStorage</code> (<code>clarae.terminal.dock</code>), non nel vault e non sincronizzate. Il pulsante <code>terminal:toggle</code> sta in ribbon sopra le Impostazioni (<code>aria-pressed</code> quando il terminale è aperto, ancorato o separato) e non compare dove la capability <code>terminal</code> manca.</li><li><strong>Finestra separata: una seconda finestra Wails v3 nello stesso processo, solo per il terminale</strong> (<code>Window.NewWithOptions</code> con <code>Name: &quot;terminal&quot;</code>, pagina <code>/terminal.html</code>). Un pulsante all&#39;estrema destra della barra dei tab la apre («Sgancia terminale») e la chiude («Aggancia a Clarae»). Le <strong>sessioni non appartengono a una finestra</strong>: le possiede il <code>Manager</code> del terminale nel core. Sganciare o agganciare cambia solo la finestra che disegna il pannello (stato <code>docked</code> | <code>detached</code>, evento <code>terminal:layout {mode}</code>): <ul><li>ogni finestra riceve gli eventi <code>terminal:output</code>, ma <strong>disegna solo chi possiede il pannello</strong> (<code>mode</code>);</li><li>chi diventa proprietario chiede <code>Snapshot</code> di ogni tab (ring buffer di output con il suo <code>seq</code>) e scarta gli eventi con <code>seq</code> minore o uguale a quello dello snapshot: output, cronologia di scorrimento e stato restano, la shell non si accorge di nulla (un <code>Resize</code> adatta il PTY alla nuova finestra);</li><li><strong>nessun altro contenuto</strong> va nella seconda finestra: il resto di Clarae resta una finestra sola (A-03 vale ancora per tutto il resto, e ADR-0051 «niente pop-out» per ogni altra vista).</li></ul></li><li><strong>Vault privati.</strong> Con il vault della scheda bloccato la scheda si copre, nella finestra principale e in quella separata (nessun output visibile, nessun tasto; i processi restano vivi). La copertura si deduce dallo stato del vault (<code>SyncAPI.Info(id).locked</code>), <strong>non dalla fase della sincronizzazione</strong>: una sincronizzazione in pausa non scopre la scheda. I tasti premuti nel terminale contano come attività per il blocco automatico (<code>api.crypto.activity</code>).</li></ol><h3 id="chiusura-dei-processi" tabindex="-1">Chiusura dei processi <a class="header-anchor" href="#chiusura-dei-processi" aria-label="Permalink to &quot;Chiusura dei processi&quot;">​</a></h3><ol start="8"><li><strong>Un tab chiuso</strong> termina la sua shell; <strong>la finestra separata chiusa dal sistema</strong> termina <strong>tutte</strong> le sessioni e riporta lo stato a <code>docked</code> con il pannello chiuso (l&#39;hook sulla sola finestra del terminale non passa dal <code>CloseGuard</code> dell&#39;app, <code>apps/desktop/internal/shell/close.go</code>, che resta della finestra principale); <strong>l&#39;uscita dell&#39;app</strong> chiude sessioni e finestra. La chiusura dell&#39;<strong>ultimo tab</strong> chiude il pannello (o la finestra).</li><li><strong>Nessun orfano.</strong> Unix: ogni shell è leader di un gruppo di processi proprio (<code>Setsid</code> e <code>Setctty</code>); alla chiusura <code>SIGHUP</code> al gruppo e, dopo 1 secondo, <code>SIGKILL</code>, poi <code>Wait</code>. Windows: <code>ClosePseudoConsole</code> e chiusura di un <strong>Job Object con <code>KILL_ON_JOB_CLOSE</code></strong>, in cui stanno i figli, così nemmeno un arresto anomalo dell&#39;app lascia processi. <code>Manager.Shutdown()</code> chiude tutto entro il watchdog di 3 secondi (<code>lifecycle.go:15</code>) ed è chiamato <strong>per primo</strong> in <code>App.Shutdown</code> (<code>app.go:237</code>), accanto a <code>shutdownWebViews</code>.</li><li><strong>Limiti.</strong> Al massimo 16 sessioni; ring buffer di 2 MiB per sessione; l&#39;output si coalesce (flush ogni circa 16 ms o 32 KiB) prima di diventare l&#39;evento <code>terminal:output {id, seq, data}</code>; <code>terminal:exit {id, code, reason}</code> segnala la fine del processo (<code>reason</code> vale <code>read-only</code> per la chiusura della decisione 4). Valori da misurare con output massivo (<code>yes</code>, <code>cat</code> di file grandi): gli eventi di Wails hanno una coda per finestra e i payload grandi passano da una richiesta.</li></ol><h3 id="interfacce" tabindex="-1">Interfacce <a class="header-anchor" href="#interfacce" aria-label="Permalink to &quot;Interfacce&quot;">​</a></h3><ol start="11"><li><strong>Binding <code>TerminalAPI</code></strong> (<code>apps/desktop/internal/app/bindings_terminal.go</code>, registrato in <code>App.Services()</code>): <code>Open(vaultId, cols, rows)</code> → <code>{id, cwd, shell}</code>, <code>Write(id, data)</code>, <code>Resize(id, cols, rows)</code>, <code>Close(id)</code>, <code>List()</code>, <code>Snapshot(id)</code> → <code>{data, seq}</code>, <code>Dock()</code>, <code>Undock()</code>, <code>State()</code>. Per i vault in sola lettura <code>Open</code> fallisce con <code>terminal-read-only</code>. Stub per WASM (<code>bindings_terminal_js.go</code>, build <code>js</code>) con l&#39;errore <code>terminal-unavailable</code>, come <code>bindings_webview_js.go</code>. Il pacchetto <code>apps/desktop/internal/terminal/</code> è escluso dalla build WASM (<code>//go:build !js</code>).</li><li><strong>Registro e capability</strong> (ADR-0037, ADR-0045): capability <code>terminal</code> in <code>apps/desktop/internal/app/capabilities.go</code> (desktop su macOS, Windows e Linux; web falsa), voce <code>terminal</code> in <code>shared/parity/features.yaml</code> con il workbench «no» (eccezione di parità), eventi in <code>events_registry.go</code>, poi <code>task gen</code>. I comandi (<code>terminal:toggle</code>, <code>terminal:new-tab</code>, <code>terminal:close-tab</code>, <code>terminal:undock</code>, <code>terminal:dock</code>) dichiarano <code>feature: &#39;terminal&#39;</code> e <code>requires: [&#39;terminal&#39;]</code>; <code>task parity</code> rifiuta ciò che non è registrato.</li></ol><p><strong>Scorciatoie (precisazioni dell&#39;implementazione).</strong> <code>terminal:toggle</code> <code>Ctrl+` </code> e <code>terminal:new-tab</code> <code>Ctrl+Maiusc+` </code> su tutti i sistemi, anche macOS (dove <code>Cmd+` </code> resta al sistema). Il tasto si riconosce prima dal carattere e poi dalla posizione fisica (<code>combosFromEvent</code>): fuori da macOS solo <code>Backquote</code>; su macOS anche <code>IntlBackslash</code>, perché una tastiera ISO riporta il tasto in alto a sinistra come <code>IntlBackslash</code> e il tasto <code>&lt;&gt;</code> come <code>Backquote</code>. Dentro xterm una combinazione riservata passa all&#39;app solo se il comando che l&#39;app eseguirebbe è <code>terminal:*</code> o la palette: con il layout italiano su Windows e Linux <code>Ctrl+\\</code> dentro il terminale resta alla shell, mentre fuori dal terminale, con una nota aperta, esegue <code>pane:split-right</code> (conflitto noto, che Impostazioni › Scorciatoie non segnala). Nella finestra separata valgono le scorciatoie del vault della scheda in primo piano (le predefinite se la scheda è nella home o le impostazioni non si leggono) e il titolo della finestra è localizzato dalla pagina. Una sessione che termina prima che la risposta di <code>Open</code> arrivi dà un tab già segnato come terminato, o nessun tab se l&#39;uscita è pulita.</p><h3 id="sicurezza-e-perimetro" tabindex="-1">Sicurezza e perimetro <a class="header-anchor" href="#sicurezza-e-perimetro" aria-label="Permalink to &quot;Sicurezza e perimetro&quot;">​</a></h3><ol start="13"><li><strong>V-02 (architettura chiusa).</strong> Il terminale non aggiunge plugin, temi, script di terze parti né CSS personalizzato: esegue <strong>i comandi che l&#39;utente digita</strong>, con i privilegi dell&#39;utente, in un processo del sistema operativo. Non carica né esegue codice di terzi dentro l&#39;app. Lo spirito di V-02 («ogni funzione è compilata nell&#39;eseguibile») non cambia, ma una shell è per natura un modo di eseguire altro codice: va dichiarato, ed è per questo che l&#39;ADR porta una sezione sullo spec.</li><li><strong>ADR-0047 (nessuna esecuzione automatica).</strong> Una shell parte <strong>solo da un gesto dell&#39;utente</strong> (pulsante, comando, <code>+</code>): niente avvio al caricamento del vault, né da un file del vault, né da un link, né da un deep link <code>clarae://</code>. Il frontend non può passare comandi o percorsi all&#39;apertura. Per questo non serve il flag del Config Profile, per decisione dell&#39;owner; resta vero che un amministratore non può spegnere il terminale (limite dichiarato nelle conseguenze).</li><li><strong>Il terminale non è una sandbox.</strong> Oltre al limite della decisione 4: l&#39;ambiente dell&#39;app è ereditato dalla shell (compresi eventuali segreti nelle variabili d&#39;ambiente dell&#39;utente), e i link che xterm riconosce (gli indirizzi nel testo e i collegamenti OSC 8 che un programma scrive: <code>linkHandler</code> in <code>terminal/instances.ts</code>) si aprono solo con <code>openExternal</code> dopo un gesto dell&#39;utente, e <code>openExternal</code> lascia passare solo indirizzi web, e-mail e telefono. Il lint <code>gosec</code> G204 (comando costruito da variabile) è soppresso con una motivazione: la shell la sceglie l&#39;utente o il sistema.</li><li><strong>Perimetro per-vault (D-06).</strong> <code>cwd</code> è la radice di un solo vault; il terminale non introduce funzioni cross-vault dell&#39;app. Dalla shell, però, l&#39;utente può fare ciò che vuole fuori dall&#39;app (decisione 4).</li></ol><h3 id="dipendenze-e-licenze-adr-0049" tabindex="-1">Dipendenze e licenze (ADR-0049) <a class="header-anchor" href="#dipendenze-e-licenze-adr-0049" aria-label="Permalink to &quot;Dipendenze e licenze (ADR-0049)&quot;">​</a></h3><ol start="17"><li>Nuove: <code>github.com/creack/pty</code> v1.1.24 (MIT; già nel <code>go.sum</code>), <code>@xterm/xterm</code>, <code>@xterm/addon-fit</code>, <code>@xterm/addon-web-links</code> (MIT). Il codice di Windows usa solo <code>golang.org/x/sys</code>, già diretta. Vanno elencate nelle <em>Licenze</em> (<code>README.md</code> e Impostazioni › Informazioni) e le versioni si fissano esatte, come per le altre dipendenze (<code>@xterm/*</code> a 6.0.0, 0.11.0 e 0.12.0 in <code>packages/workbench/package.json</code>). Le licenze effettive si ricontrollano al momento dell&#39;aggiunta (Onda C), prima di accettare l&#39;ADR nello stato finale. <strong>(Nota del 2026-11-20: l&#39;owner ha accettato l&#39;ADR prima di questo controllo; il controllo è stato fatto il 2026-11-20, a Onda C implementata: <code>@xterm/xterm</code> 6.0.0, <code>@xterm/addon-fit</code> 0.11.0, <code>@xterm/addon-web-links</code> 0.12.0 (campo <code>license</code> e file <code>LICENSE</code> dei pacchetti) e <code>github.com/creack/pty</code> v1.1.24 (<code>LICENSE</code>) sono tutti MIT. <code>packages/workbench/package.json</code> fissa ora i tre <code>@xterm/*</code> alle versioni esatte (era <code>^</code>; <code>yarn.lock</code> le fissava già). L&#39;attribuzione è nel <code>README.md</code> e in <em>Impostazioni → Informazioni → Licenze</em> (<code>settings.terminalAttribution</code>: xterm.js e creack/pty sul desktop; <code>settings.terminalAttributionWeb</code>: solo xterm.js nel workbench web, che porta il pacchetto anche senza terminale).)</strong></li></ol><h3 id="prove" tabindex="-1">Prove <a class="header-anchor" href="#prove" aria-label="Permalink to &quot;Prove&quot;">​</a></h3><ol start="18"><li>Automatiche (nelle onde A–C): test del <code>Manager</code> su Unix con <code>/bin/sh</code> reale (apertura, <code>cwd</code>, eco, resize, <code>Snapshot</code> e <code>seq</code>, rifiuto con <code>terminal-read-only</code>, chiusura delle sessioni quando il vault diventa di sola lettura, chiusura di un tab e di tutto con verifica che il gruppo di processi non esista più, figlio in background ucciso, limite di sessioni, <code>Shutdown</code> entro 3 secondi); <code>task vet-windows</code> e <code>task vet-linux</code> per ConPTY e Job Object; vet con <code>GOOS=js</code> per lo stub; vitest per il modello dei tab, le preferenze di ancoraggio, il pulsante della ribbon (anche disabilitato) e i tasti; <code>task e2e</code> sul mock dei binding (con un <code>TerminalAPI</code> finto); <code>task parity</code>.</li><li>Manuali, a carico dell&#39;owner (<a href="./../qa/m23-terminale.html"><code>docs/qa/m23-terminale.md</code></a>, scritto): shell e <code>cwd</code> su macOS, Windows e Linux; sgancio con <code>top</code> in esecuzione che continua; chiusure senza processi orfani (<code>ps</code>, Task Manager); uscita dell&#39;app; vault in sola lettura. <strong>Fino ad allora nulla è provato su una finestra reale, né su ConPTY.</strong></li></ol><h3 id="sezioni-dello-spec-da-aggiornare-a-cura-dell-owner" tabindex="-1">Sezioni dello spec da aggiornare (a cura dell&#39;owner) <a class="header-anchor" href="#sezioni-dello-spec-da-aggiornare-a-cura-dell-owner" aria-label="Permalink to &quot;Sezioni dello spec da aggiornare (a cura dell&#39;owner)&quot;">​</a></h3><p>Righe della v1.7 che cambiano; il testo applicato è in <a href="./../spec-v1.8-proposta.html"><code>../spec-v1.8-proposta.md</code></a> §5, <strong>recepito in <code>Specifications.md</code> v1.8 il 2026-11-20</strong> (i numeri di riga sono quelli della v1.7; quelli citati da ADR-0051 si riferiscono a una versione precedente):</p><ul><li><strong>A-03</strong> (<code>:70</code>): «gestisce una sola finestra per processo» e «le finestre separate (pop-out) non sono nativamente disponibili» → una finestra principale più, solo per il terminale, una seconda (Wails v3, nello stesso processo); le altre viste restano nella finestra unica.</li><li><strong>§2.2.1, riga «Finestre separate (pop-out)»</strong> (<code>:357</code>): resta P2 per ogni vista tranne il terminale; la motivazione «processo secondario con IPC locale» decade. <strong>Nuova riga «Terminale integrato»</strong> (priorità da decidere, modulo <code>terminal</code>): shell dell&#39;utente, tab, pannello ancorabile e finestra separata, <code>cwd</code> nella radice del vault, non disponibile nei vault in sola lettura, nessun flag, non nel workbench web. La riga «Pannelli, tab, split…» (<code>:356</code>, «finestra unica») precisa «a parte il terminale».</li><li><strong>§2.5, riga <code>platform</code></strong> (<code>:495</code>, «Finestra singola (Wails v2)») e <strong>§4.2</strong> (<code>:1760</code>, <code>platform/</code>): non più «finestra singola»; nuovo modulo <code>terminal</code> (<code>apps/desktop/internal/terminal/</code>), nuovo elenco delle capability (<code>:1769</code>: aggiungere <code>terminal</code>).</li><li><strong>§2.8.3, eccezioni di parità</strong> (<code>:691</code>): aggiungere «terminale integrato (il browser non può avviare processi)».</li><li><strong>§3.7</strong> (<code>:1532</code>): una riga sul terminale (shell dell&#39;utente, solo da un gesto, non è una sandbox, i vault in sola lettura non lo aprono).</li><li><strong>V-02</strong> (<code>:56</code>): una nota che il terminale esegue comandi dell&#39;utente e non codice di terzi (il testo del vincolo può restare).</li><li><strong>App. B, riga «Post-1.0 (P2)»</strong> (<code>:1939</code>, «finestre pop-out (processo secondario)»): «finestre pop-out» per le altre viste, senza «processo secondario»; <strong>C.2</strong> (<code>:1979</code>, «Pop-out rinviate (P2)»): precisare che la finestra del solo terminale è realizzata (M23) con una seconda finestra Wails v3. D-07 (<code>:1955</code>) non cambia per questo ADR (lo toccano V-07, D-07 e A-03 di ADR-0051). In C.4, una riga per ADR-0064.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Finestra separata in un processo secondario con IPC locale (come suggeriva lo spec, §2.2.1).</strong> Scartata: era la soluzione obbligata con Wails v2, che gestisce una sola finestra per processo. Con Wails v3 (ADR-0051) una seconda finestra vive nello stesso processo, e le sessioni nel core non devono attraversare un confine di processo; un secondo processo richiederebbe un canale con autenticazione, una seconda istanza dell&#39;app (conflitto con il single-instance lock) e la gestione dei processi figli in due posti.</li><li><strong>Terminale anche nel workbench web.</strong> Scartata: il browser non può avviare processi sul computer dell&#39;utente, e un terminale lato server esporrebbe una shell sul cloud (contro V-02 e il modello di sicurezza del cloud, che non interpreta il contenuto). È un&#39;eccezione di parità dichiarata.</li><li><strong>WebSocket locale tra il frontend e le sessioni.</strong> Scartata: la CSP ha <code>connect-src &#39;self&#39;</code> (<code>csp_prod.go:14</code>) e aprirla a <code>ws://127.0.0.1</code> significherebbe una porta in ascolto raggiungibile da altri processi del computer, con un segreto da gestire. Binding ed eventi Wails sono già autenticati dall&#39;app e hanno gli stessi limiti del resto dell&#39;interfaccia.</li><li><strong>Un flag del Config Profile per spegnere il terminale.</strong> Scartata per decisione dell&#39;owner (2026-11-20): il terminale è sempre disponibile sul desktop; l&#39;effetto è che un amministratore non può impedirlo (vedi «Conseguenze»).</li><li><strong><code>cwd</code> = radice del vault anche per i mount in sola lettura</strong> (decisione dell&#39;owner presa e poi sostituita il 2026-11-20). Scartata: il terminale avrebbe aggirato la sola lettura di un mount. Si rifiuta l&#39;apertura (<code>terminal-read-only</code>), con il pulsante disabilitato e la chiusura delle sessioni già aperte.</li><li><strong>Le sessioni dentro la finestra che le mostra</strong> (al riaggancio si ripartirebbe da shell nuove). Scartata: viola il requisito «senza riavviare le shell»; le sessioni stanno nel core, con snapshot e <code>seq</code> per ridisegnare.</li><li><strong><code>xterm.js</code> nel bundle iniziale.</strong> Scartata: pesa sul budget iniziale (ADR-0020, ADR-0025) per una funzione che serve a una parte degli utenti; si carica in modo lazy.</li><li><strong>Un terminale scritto a mano con un campo di testo</strong> (senza PTY). Scartata: nessun programma interattivo (<code>top</code>, editor, <code>ssh</code>) funzionerebbe.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Un amministratore non può spegnere il terminale</strong> e il terminale <strong>non rispetta la sola lettura fuori dal vault della sessione</strong>. Su un computer gestito, chi vuole limitarlo deve farlo con i mezzi del sistema operativo. Se servirà un flag, si registra come nuovo ADR (si può aggiungere <code>features.terminal</code> allo schema del Config Profile con default acceso senza rompere nulla).</li><li><strong>Prima finestra aggiuntiva del prodotto:</strong> chiusure, fuoco ed eventi doppi sono rischi nuovi, mitigati da <code>mode</code> e <code>seq</code>. Su Linux la finestra separata non ospita viste native (non servono). La finestra separata non passa dal <code>CloseGuard</code>: una chiusura dal sistema termina le shell senza chiedere conferma.</li><li><strong>ConPTY e Job Object non sono provati su Windows</strong> finché l&#39;owner non esegue il runbook; fino ad allora si compilano (<code>task vet-windows</code>) ma non girano.</li><li><strong>Throughput:</strong> un output massivo può saturare la coda degli eventi; la coalescenza lo limita e va misurato.</li><li><strong>Due finestre, una chiusura:</strong> Windows e Linux hanno comportamenti diversi nel dare il fuoco alla finestra principale quando la separata si chiude; sono nelle prove manuali.</li><li><strong>Dopo l&#39;accettazione (2026-11-20, fatto):</strong> <code>Specifications.md</code> aggiornato alla v1.8 (sezioni sopra), righe dell&#39;indice, nota in ADR-0051 (accettato lo stesso giorno, opzione A della proposta: l&#39;accettazione di ADR-0064 presupponeva il client su Wails v3), guide (utente, amministratore, sviluppo), runbook e CHANGELOG. <strong>Resta da fare:</strong> le prove manuali su macOS, Windows e Linux.</li></ul>',31)])])}const m=o(t,[["render",l]]);export{g as __pageData,m as default};
